<template><div class="page"><h2 class="page-title">预算方案记录</h2><p class="muted">每次确认重新规划都会生成新版本；旧方案只读保留，便于解释预算为什么改变。</p><el-timeline v-if="plans.length" class="section"><el-timeline-item v-for="p in plans" :key="p.id" :timestamp="localDate(p.created_at)" :type="p.is_current?'success':'info'"><el-card><div class="section-heading"><div><b>第 {{p.version}} 版预算</b><p class="muted">生成原因：{{reasonLabels[p.generation_reason]||p.generation_reason}}</p></div><div><el-tag :type="p.is_current?'success':'info'">{{planStatusLabels[p.status]||p.status}}</el-tag><el-tag v-if="p.risk_level" type="warning">变化风险 {{riskLabels[p.risk_level]||p.risk_level}}</el-tag></div></div><p>预计期末存款：{{formatMoney(p.expected_final_savings_minor)}} · {{p.parent_plan_id?`基于第 ${parentVersion(p.parent_plan_id)} 版调整`:'首次预算方案'}}</p><el-button text @click="open(p.id)">查看当时的分类预算</el-button></el-card></el-timeline-item></el-timeline><EmptyGuide v-else description="还没有预算方案记录" hint="生成并确认第一份预算后，版本会保存在这里。" action="/budgets" action-text="生成预算方案"/><el-drawer v-model="visible" title="该版本的分类预算" size="55%"><el-table :data="detail.items"><el-table-column prop="week_start" label="周开始"/><el-table-column prop="category_name" label="类别"/><el-table-column label="正常消费参考"><template #default="s">{{formatMoney(s.row.natural_spend_minor)}}</template></el-table-column><el-table-column label="当时建议预算"><template #default="s">{{formatMoney(s.row.recommended_budget_minor)}}</template></el-table-column></el-table></el-drawer></div></template>
<script setup>
import { onMounted,ref } from 'vue';import { ElMessage } from 'element-plus';import { api } from '../api/client.js';import { formatMoney } from '../utils/money.js';import { localDate,planStatusLabels,reasonLabels,riskLabels } from '../utils/display.js';import EmptyGuide from '../components/EmptyGuide.vue'
const plans=ref([]),visible=ref(false),detail=ref({items:[]});onMounted(async()=>{try{plans.value=(await api.get('/budgets')).items}catch(e){ElMessage.error(e.message)}});function parentVersion(id){return plans.value.find(x=>x.id===id)?.version||'?'}async function open(id){detail.value=await api.get(`/budgets/${id}`);visible.value=true}
</script>
